// ---------------------------------------------------------------------------
// EDIT THIS NODE AND (almost) NOTHING ELSE.
// Every downstream node reads its configuration from here.
// ---------------------------------------------------------------------------
return [
  {
    json: {
      config: {
        timezone: 'Australia/Melbourne',

        // Everyone who may take a site assessment. All of them are asked at
        // once; the first to answer "Yes" owns the meeting. `calendarId` is
        // normally the same as the work email.
        // CONFIRM THESE ADDRESSES before going live.
        team: [
          {
            key: 'kane',
            name: 'Kane',
            email: 'kane@apmgservices.com.au',
            calendarId: 'kane@apmgservices.com.au',
          },
          {
            key: 'farbod',
            name: 'Farbod',
            email: 'farbod@apmgservices.com.au',
            calendarId: 'farbod@apmgservices.com.au',
          },
          {
            key: 'simon',
            name: 'Simon',
            email: 'simon@apmgservices.com.au',
            calendarId: 'simon@apmgservices.com.au',
          },
          {
            key: 'zac',
            name: 'Zac',
            email: 'zac@apmgservices.com.au',
            calendarId: 'zac@apmgservices.com.au',
          },
        ],

        // Where the tentative hold and the final booking live. Use a shared
        // "Site assessments" calendar if you have one; the Google account
        // behind the Calendar credential must be able to write to it.
        holdCalendarId: 'kane@apmgservices.com.au',

        officeEmail: 'info@commercialpainters.com.au',
        businessName: 'Commercial Painters',
        businessPhone: '1300 97 97 40',
        officeAddress: '1 Turbo Drive, Bayswater North VIC 3153',

        // Online assessments are a short Google Meet. On-site visits are a
        // walk-through, and the assessor needs travel time either side, which
        // is held on the calendar but never shown to the client.
        online: { durationMinutes: 30, startHours: [8, 9, 10, 11, 13, 14, 15, 16] },
        onsite: { durationMinutes: 90, travelBufferMinutes: 45, startHours: [8, 10, 13, 15] },

        // On-site visits are metropolitan Melbourne only - the same rule the
        // website enforces. Anything else is routed to the office by hand.
        onsiteRegion: 'melbourne',

        workingHours: { startHour: 8, endHour: 17 },
        leadTimeHours: 24, // never propose something in the next 24 hours
        horizonDays: 14, // how far ahead to look for a slot
        confirmWithinHours: 6, // how long the team has before the office is told
        maxRounds: 4, // how many times a "No" may bounce to whoever is left
      },
    },
  },
];

// ---------------------------------------------------------------------------
// Turn the website's form payload into something a calendar can act on.
//
// Three jobs:
//   1. Map the form's enum values to the labels a human reads.
//   2. Decide whether this is bookable at all (complete? on-site in area?).
//   3. Read the free-text "preferred times" and rank every bookable slot in
//      the next fortnight against it, best first. The assessor still sees the
//      client's own words in the approval email and can move the time.
// ---------------------------------------------------------------------------

const cfg = $('Team and settings').first().json.config;
const incoming = $('Booking request received').first().json;
const body = incoming.body ?? incoming;

const text = (value) => String(value ?? '').trim();

const SITE_REGIONS = {
  melbourne: 'Metropolitan Melbourne',
  'regional-victoria': 'Elsewhere in Victoria',
  interstate: 'Interstate',
};

const ASSESSMENT_TYPES = {
  onsite: 'On-site visit',
  online: 'Online assessment',
};

const PROPERTY_TYPES = {
  'education-and-childcare': 'School or childcare',
  healthcare: 'Healthcare or medical',
  'aged-care-and-retirement': 'Aged care or retirement living',
  'body-corporate-and-strata': 'Body corporate or strata',
  retail: 'Retail',
  hospitality: 'Hospitality or venue',
  'leisure-and-sports': 'Leisure or sports facility',
  industrial: 'Industrial or warehouse',
  office: 'Office',
  other: 'Something else',
};

const booking = {
  receivedAt: new Date().toISOString(),
  name: text(body.name),
  organisation: text(body.organisation),
  email: text(body.email).toLowerCase(),
  phone: text(body.phone),
  siteRegion: text(body.siteRegion),
  siteRegionLabel: SITE_REGIONS[text(body.siteRegion)] ?? text(body.siteRegion),
  assessmentType: text(body.assessmentType),
  assessmentTypeLabel: ASSESSMENT_TYPES[text(body.assessmentType)] ?? text(body.assessmentType),
  propertyType: text(body.propertyType),
  propertyTypeLabel: PROPERTY_TYPES[text(body.propertyType)] ?? text(body.propertyType),
  siteAddress: text(body.siteAddress),
  preferredTimes: text(body.preferredTimes),
  notes: text(body.notes),
};

// -- 1. Is it bookable? -----------------------------------------------------
const problems = [];
if (text(body.company_website)) problems.push('honeypot filled');
if (booking.name.length < 2) problems.push('missing name');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(booking.email)) problems.push('missing or invalid email');
if (!ASSESSMENT_TYPES[booking.assessmentType]) problems.push('unknown assessment type');

const outOfArea = booking.assessmentType === 'onsite' && booking.siteRegion !== cfg.onsiteRegion;

const route = problems.length ? 'reject' : outOfArea ? 'out-of-area' : 'book';

if (route !== 'book') {
  return [{ json: { route, problems, outOfArea, booking, config: cfg, candidates: [] } }];
}

// -- 2. Read the client's preferred times -----------------------------------
const wanted = booking.preferredTimes.toLowerCase();

const DAY_WORDS = [
  ['monday', 1],
  ['mon', 1],
  ['tuesday', 2],
  ['tues', 2],
  ['tue', 2],
  ['wednesday', 3],
  ['weds', 3],
  ['wed', 3],
  ['thursday', 4],
  ['thurs', 4],
  ['thur', 4],
  ['thu', 4],
  ['friday', 5],
  ['fri', 5],
];

const wantedDays = new Set();
for (const [word, weekday] of DAY_WORDS) {
  if (new RegExp('\\b' + word + '\\b').test(wanted)) wantedDays.add(weekday);
}

/** Every clock time mentioned, as a decimal hour in 24h form. */
function clockTimes(source) {
  const found = [];
  const withMeridiem = /\b(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)\b/g;
  const bareColon = /\b(\d{1,2}):(\d{2})\b/g;
  let match;
  while ((match = withMeridiem.exec(source)) !== null) {
    let hour = Number(match[1]) % 12;
    if (match[3] === 'pm') hour += 12;
    found.push(hour + Number(match[2] ?? 0) / 60);
  }
  while ((match = bareColon.exec(source)) !== null) {
    found.push(Number(match[1]) + Number(match[2]) / 60);
  }
  return found;
}

const mentioned = clockTimes(wanted);
const afterMatch = /\b(?:after|from)\s+([^,.;]{1,12})/.exec(wanted);
const beforeMatch = /\b(?:before|by|until|til|till)\s+([^,.;]{1,12})/.exec(wanted);
const notBefore = afterMatch ? (clockTimes(afterMatch[1])[0] ?? null) : null;
const notAfter = beforeMatch ? (clockTimes(beforeMatch[1])[0] ?? null) : null;

/** "before Friday" names a deadline, not a preference for Friday. */
function weekdayIn(fragment) {
  for (const [word, weekday] of DAY_WORDS) {
    if (new RegExp('\\b' + word + '\\b').test(fragment)) return weekday;
  }
  return null;
}

const afterWeekday = afterMatch ? weekdayIn(afterMatch[1]) : null;
const beforeWeekday = beforeMatch ? weekdayIn(beforeMatch[1]) : null;
if (afterWeekday !== null) wantedDays.delete(afterWeekday);
if (beforeWeekday !== null) wantedDays.delete(beforeWeekday);

const saysMorning = /\b(morning|early)\b/.test(wanted);
const saysAfternoon = /\b(afternoon|arvo|late)\b/.test(wanted);
const saysAnyTime = /\b(any ?time|whenever|flexible|asap|as soon as)\b/.test(wanted);

// -- 3. Generate and rank the candidate slots -------------------------------
const shape = booking.assessmentType === 'online' ? cfg.online : cfg.onsite;
const buffer = shape.travelBufferMinutes ?? 0;

const now = DateTime.now().setZone(cfg.timezone);
const earliest = now.plus({ hours: cfg.leadTimeHours });

function scoreSlot(start, daysAhead) {
  let score = Math.max(0, 12 - daysAhead); // gentle preference for sooner
  if (saysAnyTime) return score + 5;

  const hour = start.hour + start.minute / 60;

  if (wantedDays.size) score += wantedDays.has(start.weekday) ? 45 : -18;
  if (saysMorning && !saysAfternoon) score += hour < 12 ? 22 : -12;
  if (saysAfternoon && !saysMorning) score += hour >= 12 ? 22 : -12;

  for (const target of mentioned) {
    const gap = Math.abs(hour - target);
    if (gap <= 0.25) score += 35;
    else if (gap <= 1) score += 20;
    else if (gap <= 2) score += 8;
  }

  // Softer than the day and daypart cues: "Tuesday morning or Thursday after
  // 2pm" gives two alternatives, and scoring them as one rule would rule out
  // the Tuesday the client actually offered.
  if (notBefore !== null) score += hour >= notBefore ? 16 : -8;
  if (notAfter !== null) score += hour + shape.durationMinutes / 60 <= notAfter ? 16 : -8;

  if (beforeWeekday !== null) score += start.weekday < beforeWeekday ? 14 : -14;
  if (afterWeekday !== null) score += start.weekday > afterWeekday ? 14 : -14;

  return score;
}

const candidates = [];
for (let dayOffset = 0; dayOffset <= cfg.horizonDays; dayOffset += 1) {
  const day = now.plus({ days: dayOffset }).startOf('day');
  if (day.weekday > 5) continue; // weekdays only

  for (const startHour of shape.startHours) {
    const start = day.set({ hour: startHour, minute: 0, second: 0, millisecond: 0 });
    const end = start.plus({ minutes: shape.durationMinutes });

    if (start < earliest) continue;
    if (end.hour + end.minute / 60 > cfg.workingHours.endHour) continue;

    candidates.push({
      startIso: start.toISO(),
      endIso: end.toISO(),
      // The window that must be clear on the assessor's calendar. For an
      // on-site visit that includes travel each way.
      busyStartIso: start.minus({ minutes: buffer }).toISO(),
      busyEndIso: end.plus({ minutes: buffer }).toISO(),
      travelBufferMinutes: buffer,
      durationMinutes: shape.durationMinutes,
      human:
        start.setLocale('en-AU').toFormat('cccc d LLLL') +
        ', ' +
        start.toFormat('h:mm a').toLowerCase() +
        ' to ' +
        end.toFormat('h:mm a').toLowerCase() +
        ' (Melbourne time)',
      score: scoreSlot(start, dayOffset),
    });
  }
}

candidates.sort((a, b) => b.score - a.score || a.startIso.localeCompare(b.startIso));

return [
  {
    json: {
      route,
      problems,
      outOfArea,
      booking,
      config: cfg,
      readPreferences: {
        days: [...wantedDays],
        times: mentioned,
        notBefore,
        notAfter,
        saysMorning,
        saysAfternoon,
        saysAnyTime,
      },
      candidates: candidates.slice(0, 60),
    },
  },
];

// ---------------------------------------------------------------------------
// An on-site visit was asked for somewhere the business does not send people.
// The website blocks this, so it only arrives here if the form was bypassed
// or the rule has changed. It is a real enquiry either way - hand it over.
// ---------------------------------------------------------------------------

const context = $input.first().json;
const { booking, config } = context;

const officeSubject = `On-site assessment requested outside Melbourne - ${booking.organisation}`;

const officeMessage = [
  `${booking.name} at ${booking.organisation} asked for an on-site visit, but the site is in ${booking.siteRegionLabel}.`,
  '',
  `On-site visits are ${config.onsiteRegion === 'melbourne' ? 'metropolitan Melbourne' : config.onsiteRegion} only, so nothing has been booked and no calendar hold exists.`,
  'Call them and either offer an online assessment or make a decision about the travel.',
  '',
  `SITE       ${booking.siteAddress}`,
  `SECTOR     ${booking.propertyTypeLabel}`,
  `REGION     ${booking.siteRegionLabel}`,
  '',
  'THEY ASKED FOR',
  booking.preferredTimes || '(no preference given)',
  '',
  'NOTES',
  booking.notes || '(none)',
  '',
  'CONTACT',
  `${booking.name} - ${booking.phone} - ${booking.email}`,
].join('\n');

return [{ json: { ...context, officeSubject, officeMessage } }];

// ---------------------------------------------------------------------------
// Pick the time.
//
// The ranked candidates come from the client's own words. This node crosses
// them with the team's real Google Calendar free/busy and keeps the best slot
// that at least one assessor is actually free for. Nobody is assigned yet -
// the team claims it themselves in the next step - so "free" here decides the
// time, and the email says who was free when it was proposed.
//
// For an on-site visit the window tested against the calendars includes the
// travel buffer either side, so a confirmed visit never lands back to back
// with something across town.
// ---------------------------------------------------------------------------

const setup = $('Normalise the booking').all(0, 0)[0].json;
const availability = $('Team availability (Google free-busy)').all(0, 0)[0].json;

const cfg = setup.config;
const calendars = availability.calendars ?? {};

/** Busy intervals for one calendar, as [startMs, endMs] pairs. */
function busyFor(calendarId) {
  const entry = calendars[calendarId];
  if (!entry) return { periods: [], readable: false };
  if (Array.isArray(entry.errors) && entry.errors.length) return { periods: [], readable: false };
  const periods = (entry.busy ?? []).map((p) => [Date.parse(p.start), Date.parse(p.end)]);
  return { periods, readable: true };
}

const teamBusy = cfg.team.map((member) => ({ member, ...busyFor(member.calendarId) }));
const unreadable = teamBusy.filter((t) => !t.readable).map((t) => t.member.name);

function overlaps(periods, startMs, endMs) {
  return periods.some(([busyStart, busyEnd]) => startMs < busyEnd && endMs > busyStart);
}

let chosen = null;
for (const candidate of setup.candidates) {
  const startMs = Date.parse(candidate.busyStartIso);
  const endMs = Date.parse(candidate.busyEndIso);

  const free = teamBusy
    .filter((t) => !overlaps(t.periods, startMs, endMs))
    .map((t) => t.member);

  if (!free.length) continue;

  // Preference first, but a slot more of the team can cover breaks the tie.
  const weighted = candidate.score + free.length * 3;
  if (!chosen || weighted > chosen.weighted) {
    chosen = { slot: candidate, free, weighted };
  }
}

if (!chosen) {
  return [
    {
      json: {
        ...setup,
        slotFound: false,
        reason: 'no-free-slot',
        unreadableCalendars: unreadable,
      },
    },
  ];
}

const askEmails = cfg.team.map((m) => m.email);

return [
  {
    json: {
      ...setup,
      slotFound: true,
      slot: chosen.slot,
      freeMembers: chosen.free.map((m) => m.name),
      unreadableCalendars: unreadable,
      // Who is being asked this round, and who has already said no.
      round: 1,
      declinedBy: [],
      askKeys: cfg.team.map((m) => m.key),
      askNames: cfg.team.map((m) => m.name),
      askEmails: askEmails.join(','),
    },
  },
];

// ---------------------------------------------------------------------------
// The diary had nothing. Either every working slot in the horizon collides
// with something for all four of them, or the calendars could not be read.
// Either way this is a human problem, not a retry.
// ---------------------------------------------------------------------------

const context = $input.first().json;
const { booking, config } = context;

const officeSubject = `ACTION NEEDED: no free slot for ${booking.organisation}`;

const officeMessage = [
  `A ${booking.assessmentTypeLabel.toLowerCase()} was requested and the next ${config.horizonDays} days are full for all of ${config.team.map((m) => m.name).join(', ')}.`,
  '',
  context.unreadableCalendars?.length
    ? `Could not read the calendar for: ${context.unreadableCalendars.join(', ')}. That may be the real reason - check the Google Calendar credential has access.`
    : '',
  '',
  'Nothing has been held and the client has NOT been given a time.',
  '',
  `SITE       ${booking.siteAddress}`,
  `SECTOR     ${booking.propertyTypeLabel}`,
  `REGION     ${booking.siteRegionLabel}`,
  '',
  'THEY ASKED FOR',
  booking.preferredTimes || '(no preference given)',
  '',
  'NOTES',
  booking.notes || '(none)',
  '',
  'CONTACT',
  `${booking.name} - ${booking.phone} - ${booking.email}`,
]
  .filter((line) => line !== '')
  .join('\n');

return [{ json: { ...context, officeSubject, officeMessage } }];

// ---------------------------------------------------------------------------
// One item carrying everything the rest of the workflow needs: the booking,
// the held slot, the calendar event, and the text of the email the team is
// about to receive.
//
// Whichever of the two "hold" branches ran (online or on-site) arrives here,
// so this is also where the two paths become one shape again.
// ---------------------------------------------------------------------------

const context = $('Pick the slot and who is free').all(0, 0)[0].json;
const event = $input.first().json;

const { booking, config, slot } = context;
const online = booking.assessmentType === 'online';

const meetLink =
  event.hangoutLink ??
  (event.conferenceData?.entryPoints ?? []).find((e) => e.entryPointType === 'video')?.uri ??
  '';

const lines = [
  `${booking.name} at ${booking.organisation} has asked for a free site assessment.`,
  '',
  `WHAT       ${booking.assessmentTypeLabel}${online ? ' (Google Meet)' : ' (walk-through on site)'}`,
  `WHEN       ${slot.human}`,
  online
    ? `MEET       ${meetLink || 'link on the calendar event'}`
    : `WHERE      ${booking.siteAddress}`,
  !online
    ? `TRAVEL     ${slot.travelBufferMinutes} minutes is held either side of the visit`
    : '',
  '',
  `SECTOR     ${booking.propertyTypeLabel}`,
  `REGION     ${booking.siteRegionLabel}`,
  `SITE       ${booking.siteAddress}`,
  '',
  'THEY ASKED FOR',
  booking.preferredTimes || '(no preference given)',
  '',
  'NOTES',
  booking.notes || '(none)',
  '',
  'CONTACT',
  `${booking.name} - ${booking.phone} - ${booking.email}`,
  '',
  '---',
  `Free at this time when the request came in: ${context.freeMembers.join(', ') || 'nobody'}.`,
  context.unreadableCalendars?.length
    ? `Could not read the calendar for: ${context.unreadableCalendars.join(', ')}. Check yourself before you say yes.`
    : '',
  context.declinedBy?.length
    ? `Already passed: ${context.declinedBy.join(', ')}.`
    : '',
  '',
  'Say YES and the client is sent a calendar invite immediately, with you on it',
  online ? 'and the Google Meet link.' : 'and the site address.',
  'Say NO and it goes to whoever is left. Nothing reaches the client until',
  'one of you says yes.',
  '',
  `The hold expires and the office is told if nobody answers within ${config.confirmWithinHours} hours.`,
];

const approvalMessage = lines.filter((line) => line !== '').join('\n');

const approvalSubject =
  `${context.round > 1 ? 'Still open: ' : ''}` +
  `${booking.assessmentTypeLabel} - ${booking.organisation} - ${slot.human}`;

return [
  {
    json: {
      ...context,
      event: {
        id: event.id,
        meetLink,
        htmlLink: event.htmlLink ?? '',
        calendarId: config.holdCalendarId,
      },
      approvalSubject,
      approvalMessage,
    },
  },
];

// ---------------------------------------------------------------------------
// Read what came back from the team's Yes/No form and re-attach the booking
// context, which the Gmail node does not carry through the wait.
//
// Three outcomes, and the Switch after this node routes on `outcome`:
//   confirmed  - somebody said yes and named themselves
//   declined   - somebody said no; it moves to whoever is left
//   no-answer  - the wait timed out, or the reply made no sense
// ---------------------------------------------------------------------------

const context =
  $runIndex > 0
    ? $('Note who cannot make it').all(0, $runIndex - 1)[0].json
    : $('Package the request').all(0, 0)[0].json;

const raw = $input.first().json ?? {};
const answered = raw.data ?? raw;

const pick = (...keys) => {
  for (const key of keys) {
    const value = answered[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
};

const whoAnswered = pick('Who is confirming?', 'who', 'name');
const reply = pick('Can you attend this assessment?', 'answer', 'attend');
const note = pick('Anything to add (optional)', 'note', 'message');

const saidYes = /^yes/i.test(reply) || answered.approved === true;
const saidNo = /^no/i.test(reply) || answered.approved === false;

const matched = context.config.team.find(
  (member) =>
    member.name.toLowerCase() === whoAnswered.toLowerCase() ||
    member.key === whoAnswered.toLowerCase(),
);

let outcome = 'no-answer';
if (saidYes && matched) outcome = 'confirmed';
else if (saidNo && matched) outcome = 'declined';
else if (saidYes || saidNo) outcome = 'no-answer'; // answered, but not identifiable

return [
  {
    json: {
      ...context,
      outcome,
      responder: matched ?? null,
      responderNote: note,
      rawReply: reply,
      escalationReason:
        outcome === 'no-answer'
          ? reply
            ? 'a reply came back that could not be matched to a team member'
            : `nobody answered within ${context.config.confirmWithinHours} hours`
          : '',
      owner: outcome === 'confirmed' ? matched : null,
    },
  },
];

// ---------------------------------------------------------------------------
// Somebody passed. Take them off the list and re-ask whoever is left.
//
// The hold on the calendar stays exactly where it is: one person being busy
// says nothing about the other three, and re-holding a slot invites a race.
// It is only released if the list runs out or nobody answers.
// ---------------------------------------------------------------------------

const context = $input.first().json;
const cfg = context.config;

const passed = context.responder;
const declinedBy = [...(context.declinedBy ?? []), passed?.name].filter(Boolean);
const declinedKeys = new Set(
  [...(context.declinedKeys ?? []), passed?.key].filter(Boolean),
);

const remaining = cfg.team.filter((member) => !declinedKeys.has(member.key));
const round = (context.round ?? 1) + 1;
const anyoneLeft = remaining.length > 0 && round <= cfg.maxRounds;

const passedLine = passed
  ? `${passed.name} has passed${context.responderNote ? ` - "${context.responderNote}"` : ''}.`
  : 'Someone has passed.';

const approvalMessage = [
  `STILL OPEN. ${passedLine}`,
  `Now with: ${remaining.map((m) => m.name).join(', ') || 'nobody'}.`,
  '',
  context.approvalMessage,
].join('\n');

return [
  {
    json: {
      ...context,
      round,
      declinedBy,
      declinedKeys: [...declinedKeys],
      askKeys: remaining.map((m) => m.key),
      askNames: remaining.map((m) => m.name),
      askEmails: remaining.map((m) => m.email).join(','),
      anyoneLeft,
      approvalSubject: `Still open: ${context.booking.assessmentTypeLabel} - ${context.booking.organisation} - ${context.slot.human}`,
      approvalMessage,
      escalationReason: anyoneLeft
        ? ''
        : `everyone passed (${declinedBy.join(', ')})`,
      outcome: 'declined',
      responder: null,
      owner: null,
    },
  },
];

// ---------------------------------------------------------------------------
// Nobody took it - either everyone passed or the wait ran out.
//
// The client has been told the request landed and that a time will be
// confirmed by email. Nothing has been promised, so the honest move is to put
// it in front of a human rather than auto-book somebody who never agreed.
// ---------------------------------------------------------------------------

const context = $input.first().json;
const { booking, config, slot } = context;

const officeSubject = `ACTION NEEDED: ${booking.organisation} site assessment has no assessor`;

const officeMessage = [
  `A site assessment request has not been picked up: ${context.escalationReason || 'no assessor confirmed'}.`,
  '',
  'The hold on the calendar has been released, so nothing is double-booked.',
  'The client has NOT been given a time. They are expecting an email.',
  '',
  `WHAT       ${booking.assessmentTypeLabel}`,
  `PROPOSED   ${slot?.human ?? 'no slot was proposed'}`,
  `SITE       ${booking.siteAddress}`,
  `SECTOR     ${booking.propertyTypeLabel}`,
  `REGION     ${booking.siteRegionLabel}`,
  '',
  'THEY ASKED FOR',
  booking.preferredTimes || '(no preference given)',
  '',
  'NOTES',
  booking.notes || '(none)',
  '',
  'CONTACT',
  `${booking.name} - ${booking.phone} - ${booking.email}`,
  '',
  context.declinedBy?.length ? `Passed: ${context.declinedBy.join(', ')}.` : '',
  `Ring them on ${booking.phone} and sort a time by hand.`,
]
  .filter((line) => line !== '')
  .join('\n');

return [{ json: { ...context, officeSubject, officeMessage } }];
